package wgmodern;
import java.util.*;import net.minecraft.core.*;import net.minecraft.nbt.*;import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.item.context.BlockPlaceContext;import net.minecraft.world.phys.*;import net.minecraft.world.phys.shapes.*;import tc4revival.aspect.*;import tc4revival.content.*;
public class MirrorPump extends BaseEntityBlock {
 public MirrorPump(){super(Properties.copy(Blocks.IRON_BLOCK).strength(4,9).isValidSpawn((state,level,pos,type)->false).noOcclusion());registerDefaultState(stateDefinition.any().setValue(SpinningWheel.FACING,Direction.NORTH));}
 @Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){b.add(SpinningWheel.FACING);}@Override public BlockState getStateForPlacement(BlockPlaceContext c){return defaultBlockState().setValue(SpinningWheel.FACING,c.getHorizontalDirection());}
 @Override public RenderShape getRenderShape(BlockState s){return RenderShape.ENTITYBLOCK_ANIMATED;}@Override public BlockEntity newBlockEntity(BlockPos p,BlockState s){return new Tile(p,s);}
 @Override public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level l,BlockState s,BlockEntityType<T> t){return l.isClientSide?null:createTickerHelper(t,Content.PUMP_TILE.get(),Tile::tick);}
 @Override public VoxelShape getShape(BlockState s,BlockGetter l,BlockPos p,CollisionContext c){return switch(s.getValue(SpinningWheel.FACING)){case EAST->Block.box(4,0,0,16,16,16);case WEST->Block.box(0,0,0,12,16,16);case SOUTH->Block.box(0,0,4,16,16,12);default->Shapes.block();};}
 public static class Tile extends BlockEntity implements thaumcraft.api.aspects.IEssentiaTransport {
  public Aspect aspect;public int amount;
  public Tile(BlockPos p,BlockState s){super(Content.PUMP_TILE.get(),p,s);}public Direction facing(){return getBlockState().getValue(SpinningWheel.FACING);}
  public static void tick(Level l,BlockPos p,BlockState s,Tile tile){if(!tc4revival.config.TCConfig.SERVER.allowMirrors.get()||tile.amount>=1)return;var front=p.relative(tile.facing());if(!l.hasChunkAt(front)||!(l.getBlockEntity(front) instanceof EssentiaTransport transport))return;var a=transport.suctionType(tile.facing().getOpposite());if(a==null||(tile.aspect!=null&&!tile.aspect.equals(a)))return;for(var mirror:tile.mirrors())if(mirror.takeFromContainer(a,1)){tile.aspect=a;tile.amount=1;tile.changed();tc4revival.network.EssentiaSourcePacket.send((ServerLevel)l,p,mirror.getBlockPos(),a.color());return;}}
  public List<EssentiaMirrorBlockEntity> mirrors(){var out=new ArrayList<EssentiaMirrorBlockEntity>();if(level==null)return out;var rear=facing().getOpposite();int x0=(worldPosition.getX()-8)>>4,x1=(worldPosition.getX()+8)>>4,z0=(worldPosition.getZ()-8)>>4,z1=(worldPosition.getZ()+8)>>4;for(int x=x0;x<=x1;x++)for(int z=z0;z<=z1;z++){var c=level.getChunkSource().getChunk(x,z,false);if(c==null)continue;for(var be:c.getBlockEntities().values())if(be instanceof EssentiaMirrorBlockEntity mirror&&!be.isRemoved()){var delta=be.getBlockPos().subtract(worldPosition);int length=delta.getX()*rear.getStepX()+delta.getZ()*rear.getStepZ(),width=rear.getAxis()==Direction.Axis.X?delta.getZ():delta.getX();if(length>0&&length<8&&Math.abs(delta.getY())<=8&&Math.abs(width)<=8&&canSee(mirror))out.add(mirror);}}out.sort(Comparator.comparingInt((EssentiaMirrorBlockEntity m)->m.getBlockPos().getY()).thenComparingInt(m->rear.getAxis()==Direction.Axis.X?m.getBlockPos().getZ():m.getBlockPos().getX()).thenComparingInt(m->{var d=m.getBlockPos().subtract(worldPosition);return d.getX()*rear.getStepX()+d.getZ()*rear.getStepZ();}));return out;}
  public boolean canSee(EssentiaMirrorBlockEntity mirror){var rear=facing().getOpposite();var start=Vec3.atCenterOf(worldPosition).add(rear.getStepX(),rear.getStepY(),rear.getStepZ());var f=mirror.facing();/* Original and GTNH intentionally retained: Y/Z use the pump's coordinates. */var end=new Vec3(mirror.getBlockPos().getX()+.5+f.getStepX(),worldPosition.getY()+.5+f.getStepY(),worldPosition.getZ()+.5+f.getStepZ());var hit=level.clip(new ClipContext(start,end,ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,null));return hit.getType()==HitResult.Type.MISS||hit.getBlockPos().equals(worldPosition)||hit.getBlockPos().equals(mirror.getBlockPos());}
  public void changed(){setChanged();if(level!=null&&!level.isClientSide)level.sendBlockUpdated(worldPosition,getBlockState(),getBlockState(),2);}
  @Override public boolean connectable(Direction f){return f==facing();}@Override public boolean canInput(Direction f){return false;}@Override public boolean canOutput(Direction f){return connectable(f);}@Override public Aspect suctionType(Direction f){return null;}@Override public int suction(Direction f){return 0;}@Override public int minimumSuction(){return 0;}@Override public Aspect essentiaType(Direction f){return aspect;}@Override public int essentiaAmount(Direction f){return amount;}
  @Override public int addEssentia(Aspect a,int n,Direction f){return 0;}@Override public int takeEssentia(Aspect a,int n,Direction f){if(!canOutput(f)||a==null||!a.equals(aspect)||n<=0||amount<n)return 0;amount-=n;if(amount==0)aspect=null;changed();return n;}
  @Override protected void saveAdditional(CompoundTag t){super.saveAdditional(t);t.putInt("amount",amount);if(aspect!=null)t.putString("aspect",aspect.tag());}@Override public void load(CompoundTag t){super.load(t);aspect=TCAspects.catalog().find(t.getString("aspect")).orElse(null);amount=aspect==null?0:Math.max(0,Math.min(1,t.getInt("amount")));if(amount==0)aspect=null;}
  @Override public CompoundTag getUpdateTag(){return saveWithoutMetadata();}@Override public ClientboundBlockEntityDataPacket getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}
 }
}
